package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamBotanyBank1 {
  private const val T = "ශාක ක්‍රියාකාරීත්වය, ප්‍රභාසංස්ලේෂණය හා පරිවහනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ශාක ජීව විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ප්‍රභාසංස්ලේෂණයේදී සූර්යාලෝක ශක්තිය අවශෝෂණය කර ගැනීමට දායක වන ප්‍රධාන වර්ණකය කුමක්ද?", "ක්ලෝරොෆිල් (හරිතප්‍රද)", "ඇන්තොසයනින්", "මෙලනින්", "හිමොග්ලොබින්", "හරිතප්‍රද හරිතලවවල තයිලකොයිඩ පටල මත පිහිටා ඇත."),
    q("ප්‍රභාසංස්ලේෂණ ක්‍රියාවලිය සඳහා ශාක වායුගෝලයෙන් ලබාගන්නා අමුද්‍රව්‍යය කුමක්ද?", "කාබන් ඩයොක්සයිඩ්", "ඔක්සිජන්", "නයිට්‍රජන්", "මීතේන්", "පත්‍ර රන්ධ්‍ර හරහා කාබන් ඩයොක්සයිඩ් විසරණය වේ."),
    q("ප්‍රභාසංස්ලේෂණයේදී නිපදවෙන ඔක්සිජන් වායුව ලැබෙන්නේ කුමන අමුද්‍රව්‍යය බිඳවැටීමෙන්ද?", "ජලය", "කාබන් ඩයොක්සයිඩ්", "ග්ලූකෝස්", "හරිතප්‍රද", "ආලෝක ප්‍රතික්‍රියාවේදී ජල අණු ප්‍රකාශ විච්ඡේදනය වීමෙන් O₂ නිදහස් වේ."),
    q("ශාක පත්‍රයක පිෂ්ඨය නිපදවී ඇති බව තහවුරු කිරීමේ පරීක්ෂණයේදී පත්‍රය මුලින්ම නටන ජලයේ තම්බන්නේ ඇයි?", "සෛල මරා පටල පාරගම්‍ය කිරීමට", "හරිතප්‍රද දිය කර ඉවත් කිරීමට", "පිෂ්ඨය ග්ලූකෝස් කිරීමට", "පත්‍රය සිසිල් කිරීමට", "නටන ජලයේ තැම්බීමෙන් එන්සයිම ක්‍රියාව නවතා සෛල මෘදු කරයි."),
    q("පිෂ්ඨ පරීක්ෂණයේදී ශාක පත්‍රය උණුසුම් එතනෝල් ද්‍රාවණයක ගිල්වා රත් කරන්නේ කුමක් සඳහාද?", "හරිතප්‍රද දිය කර පත්‍රය අවර්ණ කිරීමට", "පිෂ්ඨය නිපදවීමට", "සෛල බිත්ති බිඳ දැමීමට", "ජලය උරා ගැනීමට", "හරිතප්‍රද ඉවත් කළ විට අයඩින් වර්ණ විපර්යාසය පැහැදිලිව පෙනේ."),
    q("ප්‍රභාසංස්ලේෂණය පිළිබඳ පරීක්ෂණයක් ආරම්භ කිරීමට පෙර පෝච්චි කළ ශාකය පැය 48 ක් අඳුරේ තබන්නේ ඇයි?", "පත්‍රවල ඇති සියලු පිෂ්ඨය ඉවත් කිරීමට", "හරිතප්‍රද වැඩි කිරීමට", "මුල් දිගු කිරීමට", "උත්ස්වේදනය වැඩි කිරීමට", "අඳුරේ තැබීමෙන් පිෂ්ඨය පරිවහනය වී පත්‍ර පිෂ්ඨ රහිත වේ."),
    q("ප්‍රභාසංස්ලේෂණය සඳහා CO₂ අවශ්‍ය බව පෙන්වන පරීක්ෂණයේදී බෝතලය තුළ පොටෑසියම් හයිඩ්‍රොක්සයිඩ් (KOH) තබන්නේ ඇයි?", "බෝතලය තුළ ඇති CO₂ අවශෝෂණය කිරීමට", "O₂ වායුව නිපදවීමට", "ජල වාෂ්ප සැපයීමට", "පත්‍රය කොළ පැහැ කිරීමට", "KOH මගින් CO₂ උරා ගන්නා බැවින් එම පත්‍ර කොටස පිෂ්ඨය නොසාදයි."),
    q("ප්‍රභාසංස්ලේෂණයේදී හරිතප්‍රද අවශ්‍ය බව පෙන්වීම සඳහා පරීක්ෂණයට යොදාගත යුතු වඩාත් සුදුසු ශාක පත්‍රය කුමක්ද?", "විචිත්‍ර පත්‍රයක් (කොළ හා සුදු පැහැති)", "සම්පූර්ණ කොළ පැහැ පත්‍රයක්", "වියළි වැටුණු පත්‍රයක්", "ළපටි රතු අංකුරයක්", "විචිත්‍ර පත්‍රයේ කොළ පැහැ ප්‍රදේශවල පමණක් පිෂ්ඨය සෑදේ."),
    q("ජලජ ශාකයක් වන හයිඩ්‍රිල්ලා මඟින් ප්‍රභාසංස්ලේෂණයේදී පිටවන වායු බුබුළු පරීක්ෂා කළ විට පුපුරා දැල්වෙන ඉරටුවක් දීප්තිමත්ව ඇවිලෙන්නේ එහි කුමක් ඇති නිසාද?", "ඔක්සිජන් වායුව", "හයිඩ්‍රජන් වායුව", "කාබන් ඩයොක්සයිඩ්", "නයිට්‍රජන් වායුව", "ඔක්සිජන් දහනයට ආධාර කරන වායුවකි."),
    q("ප්‍රභාසංස්ලේෂණයේදී ප්‍රධාන ශක්ති පරිවර්තනය කුමක්ද?", "ආලෝක ශක්තිය රසායනික ශක්තිය බවට", "රසායනික ශක්තිය තාප ශක්තිය බවට", "විද්‍යුත් ශක්තිය ආලෝක ශක්තිය බවට", "යාන්ත්‍රික ශක්තිය රසායනික ශක්තිය බවට", "ආලෝක ශක්තිය ග්ලූකෝස් බන්ධන තුළ රසායනික ශක්තිය ලෙස ගබඩා වේ."),
    q("ශාක පත්‍රවල නිපදවෙන ග්ලූකෝස් ශාකයේ අනෙක් කොටස් කරා ෆ්ලෝයමය ඔස්සේ පරිවහනය කෙරෙන්නේ කුමන සීනි ආකාරයෙන්ද?", "සුක්‍රෝස්", "පිෂ්ඨය", "සෙලියුලෝස්", "ලැක්ටෝස්", "සුක්‍රෝස් ජලයේ හොඳින් දියවන හා නිෂ්ක්‍රීය ප්‍රවාහන සීනි වර්ගයකි."),
    q("ශාකයක ජලය හා ඛනිජ ලවණ මුල්වල සිට පත්‍ර දක්වා ඉහළට පරිවහනය කරන පටකය කුමක්ද?", "සෛලම පටකය", "ෆ්ලෝයම පටකය", "මෘදුස්තර පටකය", "කැම්බියම", "සෛලම වාහිනී හා වාහිනිකා මඟින් ඉහළට ජලය ගෙන යයි."),
    q("ශාක පත්‍රයේ ඇති කුමන ස්තරයේ වැඩිම හරිතලව සංඛ්‍යාවක් පිහිටා ඇත්ද?", "උත්තම්භ මෘදුස්තරය (Palisade mesophyll)", "උඩු අපිචර්මය", "යටි අපිචර්මය", "උච්චර්මය", "ආලෝකය සෘජුව වැටෙන උඩු පෘෂ්ඨයට ආසන්නව උත්තම්භ මෘදුස්තරය පිහිටයි."),
    q("පත්‍ර රන්ධ්‍ර විවෘත වීම හා වැසීම සෘජුවම පාලනය වන්නේ කුමන සෛලවල ශූනතාව වෙනස් වීමෙන්ද?", "පාලක සෛල", "අපිචර්ම සෛල", "සෛලම වාහිනී", "පෙනේර නාල සෛල", "පාලක සෛල ජලය උරාගෙන පිම්බුණු විට රන්ධ්‍ර විවෘත වේ."),
    q("පත්‍ර රන්ධ්‍ර වැඩි වශයෙන් පිහිටා ඇත්තේ ද්විබීජ පත්‍රී ශාක පත්‍රයක කුමන පෘෂ්ඨයේද?", "යටි පෘෂ්ඨයේ", "උඩු පෘෂ්ඨයේ", "පත්‍ර නාරටිය මත", "පත්‍ර දාරයේ පමණි", "සෘජු හිරු එළියෙන් ජල හානිය අවම කිරීමට යටි පෘෂ්ඨයේ රන්ධ්‍ර බහුලය."),
    q("ශාක පත්‍රවලින් ජලය වාෂ්ප ආකාරයෙන් වායුගෝලයට පිටවීමේ ක්‍රියාවලිය කුමක්ද?", "උත්ස්වේදනය", "බිංදුදය", "ආස්‍රැතිය", "ප්‍රභාසංස්ලේෂණය", "ප්‍රධාන වශයෙන් පත්‍ර රන්ධ්‍ර හරහා උත්ස්වේදනය සිදුවේ."),
    q("වායුගෝලයේ සාපේක්ෂ ආර්ද්‍රතාව ඉතා ඉහළ ගිය විට ශාකයක උත්ස්වේදන සීඝ්‍රතාවට කුමක් සිදුවේද?", "අඩු වේ", "වැඩි වේ", "නොවෙනස්ව පවතී", "දෙගුණ වේ", "පරිසරයේ ජල වාෂ්ප වැඩි නිසා සාන්ද්‍රණ අනුක්‍රමණය අඩු වී උත්ස්වේදනය අඩුවේ."),
    q("පහත සඳහන් සාධක අතරින් ශාකයක උත්ස්වේදන සීඝ්‍රතාව වැඩි කරන සාධකය කුමක්ද?", "සුළඟ හා ඉහළ උෂ්ණත්වය", "අධික ආර්ද්‍රතාව", "අඳුර", "පත්‍ර රන්ධ්‍ර වැසීම", "සුළඟ මඟින් පත්‍රය අවට ජල වාෂ්ප ඉවත් කරන බැවින් උත්ස්වේදනය වේගවත් වේ."),
    q("උත්ස්වේදන සීඝ්‍රතාව ආසන්න වශයෙන් මැන ගැනීම සඳහා පාසල් විද්‍යාගාරයේදී භාවිත කරන උපකරණය කුමක්ද?", "ගැනොන්ගේ පෝටෝමීටරය", "බැරෝමීටරය", "ඇමීටරය", "ඕක්සැනොමීටරය", "පෝටෝමීටරයෙන් මැන ගන්නේ ශාක අත්ත ජලය උරා ගන්නා සීඝ්‍රතාවයි."),
    q("උදෑසන කාලයේදී තෘණ හා තක්කාලි පත්‍ර දාරවලින් ජල බිංදු ලෙස ජලය පිටවීම හඳුන්වන්නේ කුමන නමින්ද?", "බිංදුදය (Guttation)", "උත්ස්වේදනය", "ඝනීභවනය", "ප්ලාස්ම විච්ඡේදනය", "මූල පීඩනය නිසා ජල රන්ධ්‍ර (Hydathodes) හරහා ද්‍රව ජලය පිටවේ."),
    q("උස ගස්වල මුදුන් දක්වා ජලය ඉහළට ඇද ගැනීමට ප්‍රධාන වශයෙන් හේතු වන බලය කුමක්ද?", "උත්ස්වේදන ඇදුම", "ගුරුත්වාකර්ෂණය", "විසරණය පමණි", "ෆ්ලෝයම පීඩනය", "උත්ස්වේදනය නිසා සෛලම කඳ තුළ ඇතිවන චූෂණ බලය ජලය ඉහළට අදී."),
    q("පසේ ඇති ජලය මූල කේශ සෛල තුළට ඇතුළු වන භෞතික ක්‍රියාවලිය කුමක්ද?", "ආස්‍රැතිය", "උත්ස්වේදනය", "ප්ලාස්ම විච්ඡේදනය", "වාෂ්පීකරණය", "මූල කේශ සෛල යුෂයේ ද්‍රාව්‍ය සාන්ද්‍රණය පස් ජලයට වඩා වැඩි බැවින් ජලය ඇතුළු වේ."),
    q("පසේ ඇති නයිට්‍රේට් හා පොටෑසියම් වැනි ඛනිජ අයන සාන්ද්‍රණය අඩු පසේ සිට මූල කේශ තුළට උරා ගන්නේ කෙසේද?", "සක්‍රිය පරිවහනය මඟින්", "ආස්‍රැතිය මඟින්", "විසරණයෙන් පමණක්", "කේශාකර්ෂණයෙන්", "ATP ශක්තිය වැය කර සක්‍රිය පරිවහනයෙන් ඛනිජ අයන අවශෝෂණය කෙරේ."),
    q("ප්‍රභාසංස්ලේෂණ සීඝ්‍රතාව සීමා කරන ප්‍රධාන බාහිර සාධක තුන මොනවාද?", "ආලෝක තීව්‍රතාව, CO₂ සාන්ද්‍රණය හා උෂ්ණත්වය", "සුළඟ, පීඩනය හා නයිට්‍රජන්", "ඔක්සිජන්, ආර්ද්‍රතාව හා pH", "මූල පීඩනය, ගුරුත්වය හා ලවණ", "මේවායින් අවම මට්ටමේ පවතින සාධකය සීමාකාරී සාධකය වේ."),
    q("ද්විබීජ පත්‍රී ශාක කඳක සෛලම පටකයේ පිහිටීමට සාපේක්ෂව ෆ්ලෝයම පටකය පිහිටන්නේ කොහේද?", "සනාල කලාපයේ පිටතට වන්නට", "සනාල කලාපයේ ඇතුළත මධ්‍යයට වන්නට", "මජ්ජාව මැද", "උච්චර්මයට පිටතින්", "පිටතින් ෆ්ලෝයමය ද මැදින් කැම්බියම ද ඇතුළතින් සෛලමය ද පිහිටයි."),
    q("ශාක කඳක වටේට පොත්ත (ෆ්ලෝයමය ඇතුළුව) මුදුවක් ලෙස ඉවත් කළ විට ඉහළ කොටස ඉදිමී යන්නේ ඇයි?", "කාබනික ආහාර පහළට පරිවහනය වීම නැවතීම නිසා", "ජලය ඉහළට යාම නැවතීම නිසා", "ඔක්සිජන් නොලැබීම නිසා", "බැක්ටීරියා ආසාදනය නිසා", "මෙම වළයාකාර පොතු ගැලවීමේ පරීක්ෂණය ෆ්ලෝයම පරිවහනය තහවුරු කරයි."),
    q("ශාකයක ප්‍රකාශවර්තන (Phototropism) ප්‍රතිචාරය පාලනය කරන ප්‍රධාන ශාක වර්ධක හෝමෝනය කුමක්ද?", "ඔක්සීන් (Auxin)", "එතිලීන්", "ඇබ්සිසික් අම්ලය", "ඉන්සියුලින්", "ඔක්සීන් අඳුරු පැත්තේ වැඩිපුර එක්රැස් වී සෛල දික් වීම වැඩි කරයි."),
    q("පළතුරු ඉදීම ඉක්මන් කිරීම සඳහා කෘෂිකර්මාන්තයේදී භාවිත කරන වායුමය ශාක හෝමෝනය කුමක්ද?", "එතිලීන්", "ඔක්සීන්", "ජිබරලීන්", "සයිටොකයිනින්", "ඉදෙන පළතුරුවලින් ස්වභාවිකව එතිලීන් පිටවේ."),
    q("ශාක මුල් පොළොව දෙසට (පහළට) වර්ධනය වීම හඳුන්වන්නේ කුමන වර්තන චලනය ලෙසද?", "ධන ගුරුත්වවර්තනය", "ඍණ ගුරුත්වවර්තනය", "ධන ප්‍රකාශවර්තනය", "සන්නමන චලනය", "ශාක කඳ ඍණ ගුරුත්වවර්තනයක් ද මුල් ධන ගුරුත්වවර්තනයක් ද පෙන්වයි."),
    q("නිදිකුම්බා පත්‍ර ඇල්ලූ විගස හැකිලී යාම කුමන ආකාරයේ ශාක චලනයක්ද?", "ස්පර්ශසන්නමන චලනය", "ප්‍රකාශවර්තන චලනය", "ජලවර්තන චලනය", "රසායනිකවර්තනය", "පත්‍රිකා පාදයේ ඇති පල්වයිනස්වල ශූනතාව වෙනස් වීමෙන් මෙය සිදුවේ."),
    q("පුෂ්පයක පරාග නිපදවන පුරුෂ ප්‍රජනක කොටස කුමක්ද?", "රේණුවේ පරාගධානිය", "ඩිම්බකෝෂය", "කලංකය", "මණි පත්‍ර", "පුමංගය පරාගධානිය හා සූත්‍රිකාවෙන් සමන්විත වේ."),
    q("පුෂ්පයක ජායාංගයට අයත් ප්‍රධාන කොටස් තුන මොනවාද?", "කලංකය, කීලය, ඩිම්බකෝෂය", "පරාගධානිය, සූත්‍රිකාව, දළ", "මණිපත්‍ර, දළ පත්‍ර, පුෂ්පාසනය", "බීජාණු, පරාග, කීලය", "ඩිම්බකෝෂය තුළ ඩිම්බ පිහිටා ඇත."),
    q("දීප්තිමත් වර්ණ දළ පත්‍ර, මිහිරි සුවඳ සහ මධු කෝෂ ඇති පුෂ්පයක් ප්‍රධාන වශයෙන් පරාගණය වන්නේ කුමක් මඟින්ද?", "කෘමීන් මඟින්", "සුළඟ මඟින්", "ජලය මඟින්", "ගුරුත්වය මඟින්", "කෘමි පරාගිත පුෂ්පවල ඇලෙන සුළු පරාග ඇත."),
    q("සුළඟින් පරාගණය වන වී හා බඩඉරිඟු වැනි පුෂ්පවල දැකිය හැකි ප්‍රධාන අනුවර්තනය කුමක්ද?", "පිහාටු වැනි කලංක සහ සැහැල්ලු පරාග රාශියක් තිබීම", "විශාල වර්ණවත් දළ පත්‍ර තිබීම", "අධික පැණි නිපදවීම", "තියුණු සුවඳක් තිබීම", "සුළඟට පහසුවෙන් ගසාගෙන යා හැකි සැහැල්ලු පරාග විශාල සංඛ්‍යාවක් නිපදවේ."),
    q("සපුෂ්ප ශාකයක සංසේචනයෙන් පසු ඩිම්බකෝෂය විකසනය වී සෑදෙන ව්‍යුහය කුමක්ද?", "ඵලය", "බීජය", "පරාග නාලය", "භ්‍රෑණ පෝෂය", "ඩිම්බය බීජය බවටත් ඩිම්බකෝෂය ඵලය බවටත් පත්වේ."),
    q("පොල් සහ දියකදුරු වැනි ශාකවල ඵල හා බීජ ව්‍යාප්ත වන ප්‍රධාන ක්‍රමය කුමක්ද?", "ජලය මඟින්", "සුළඟ මඟින්", "සතුන් මඟින්", "ස්ඵෝටන ක්‍රමයෙන්", "පාවීම සඳහා තන්තුමය පොතු හෝ වායු කුහර පිහිටා ඇත."),
    q("වරා, හොර සහ මහෝගනී වැනි ශාක බීජ ව්‍යාප්තිය සඳහා දරන විශේෂ අනුවර්තනය කුමක්ද?", "රෝම කලාප හෝ පියාපත් වැනි කොටස් තිබීම", "කටු හෝ කොකු තිබීම", "මිහිරි මාංසල පොත්තක් තිබීම", "ජල රෝධක ඉටි ස්තරයක් තිබීම", "සුළඟේ පාවී යාමට මෙම ව්‍යුහ උපකාරී වේ."),
    q("මව් ශාකයේ ලක්ෂණ නොවෙනස්ව පවත්වා ගනිමින් කෙටි කාලයකින් පැළ විශාල ගණනක් නිපදවිය හැකි කෘත්‍රිම ප්‍රචාරණ ක්‍රමය කුමක්ද?", "පටක රෝපණය", "බීජ පැළ කිරීම", "පර පරාගණය", "බීජාණු රෝපණය", "පටක රෝපණය මගින් රෝග රහිත ඒකාකාර පැළ නිපදවිය හැක."),
    q("බීජ ප්‍රරෝහණය සඳහා අනිවාර්යයෙන්ම අවශ්‍ය වන බාහිර සාධක තුන මොනවාද?", "ජලය, ඔක්සිජන් සහ හිතකර උෂ්ණත්වය", "හිරු එළිය, පස සහ නයිට්‍රජන්", "CO₂, හරිතප්‍රද සහ පොහොර", "වර්ෂාව, සුළඟ සහ CO₂", "බොහෝ බීජ ප්‍රරෝහණයට ආලෝකය අත්‍යවශ්‍ය නොවේ."),
    q("ශාක පත්‍ර පරිසර උෂ්ණත්වයෙන් අධික ලෙස රත් නොවී සිසිල්ව තබා ගැනීමට උපකාරී වන ක්‍රියාවලිය කුමක්ද?", "උත්ස්වේදනය", "ප්‍රභාසංස්ලේෂණය", "ශ්වසනය", "ද්විතීයික වර්ධනය", "ජලය වාෂ්පීකරණයේදී පත්‍රයෙන් ගුප්ත තාපය ලබා ගන්නා නිසා ශාකය සිසිල් වේ."),
    q("සෛලම පටකයේ අන්තර්ගත වන ජලය පරිවහනය කරන ප්‍රධාන ව්‍යුහ මොනවාද?", "සෛලම වාහිනී හා වාහිනිකා", "පෙනේර නාල හා සහචර සෛල", "මෘදුස්තර හා කැම්බියම", "මූල කේශ හා පාලක සෛල", "සෛලම වාහිනී ලිග්නින් තැන්පත් වූ අජීවී නාල වේ."),
    q("ෆ්ලෝයම පටකය ඔස්සේ ආහාර පරිවහනය කිරීම සඳහා ශක්තිය සපයමින් පෙනේර නාලයට සහය වන සෛල මොනවාද?", "සහචර සෛල", "සෛලම වාහිනිකා", "දෘඪස්තර තන්තු", "ස්ථූලකෝණාස්තර සෛල", "පෙනේර නාල සෛලවල න්‍යෂ්ටිය නොමැති නිසා සහචර සෛල ක්‍රියාව පාලනය කරයි."),
    q("පත්‍රයක විනිවිද පෙනෙන උඩු අපිචර්මයේ ඇති ප්‍රධාන වාසිය කුමක්ද?", "පහළ ඇති මධ්‍යස්තර සෛලවලට ආලෝකය ගමන් කිරීමට ඉඩ දීම", "CO₂ වායුව ගබඩා කිරීම", "ප්‍රෝටීන ජීර්ණය කිරීම", "ජලය පිටතට යැවීම", "අපිචර්ම සෛලවල (පාලක සෛල හැර) හරිතලව නොමැත."),
    q("වියළි පරිසරවල වැඩෙන ශුෂ්ක ශාකවල (උදා: පතොක්) උත්ස්වේදනය අවම කිරීමට ඇති අනුවර්තනයක් කුමක්ද?", "පත්‍ර කටු බවට පත්වීම", "පත්‍ර ඉතා පළල් වීම", "රන්ධ්‍ර උඩු පැත්තේ පිහිටීම", "තුනී උච්චර්මයක් තිබීම", "කටු බවට පත්වීමෙන් පෘෂ්ඨීය වර්ගඵලය අඩු වී ජල හානිය වළකී."),
    q("පැළෑටියක කඳ පොළොවට ඉහළින් කපා ඉවත් කළ විට කැපුම් පෘෂ්ඨයෙන් දියර කාන්දු වීමට හේතු වන පීඩනය කුමක්ද?", "මූල පීඩනය", "වායුගෝලීය පීඩනය", "ආස්‍රැති විභවය පමණක්", "උත්ස්වේදන ඇදුම", "මූල පීඩනය මුල් සෛලවල සක්‍රිය අයන අවශෝෂණය නිසා ඇතිවේ."),
    q("ශාක පටකවල අනවශ්‍ය වියළීම වැළැක්වීමට උපකාරී වන පත්‍ර මතුපිට ඇති ස්තරය කුමක්ද?", "ඉටිමය උච්චර්මය", "සෛලම පටකය", "සවිවර පටලය", "මධ්‍යස්තරය", "උච්චර්මය ජලයට අපාරගම්‍ය වේ."),
    q("සපුෂ්ප ශාකයක ස්ව-පරාගණය වැළැක්වීම සඳහා ඇති ස්වභාවික අනුවර්තනයක් වන්නේ කුමක්ද?", "එකම ශාකයේ පුමංගය හා ජායාංගය විවිධ කාලවල පරිණත වීම", "පුෂ්ප පෙති නොතිබීම", "මල් විවෘත නොවීම", "පරාගධානි හා කලංකය ස්පර්ශ වීම", "පර පරාගණය මඟින් ජානමය විවිධත්වය වැඩි වේ."),
    q("එක් ශාකයක ශාඛාවක් පොළොව මත පහත් කර පස්වලින් යට කර මුල් අද්දවා නව පැළයක් ලබා ගැනීමේ ක්‍රමය කුමක්ද?", "අතු බැඳීම (Layering)", "බද්ධ කිරීම (Grafting)", "අංකුර බද්ධය", "පටක රෝපණය", "දෙහි, පේර සහ රෝස වැනි ශාකවල අතු බැඳීම භාවිත කෙරේ."),
    q("බද්ධ කිරීමේදී මූල පද්ධතිය සපයන පහළ කොටස හඳුන්වන්නේ කුමන නමින්ද?", "ග්‍රාහකය (Stock)", "අනුජය (Scion)", "කැම්බියම", "කඳු මුල", "රෝගවලට ඔරොත්තු දෙන ශක්තිමත් ප්‍රභේදයක් ග්‍රාහකය ලෙස තෝරා ගනී."),
    q("ගුණාත්මක අස්වැන්නක් ලබා ගැනීමට ග්‍රාහකය මත බද්ධ කරන ඉහළ ශාක කොටස හඳුන්වන්නේ කෙසේද?", "අනුජය (Scion)", "ග්‍රාහකය (Stock)", "ප්‍රරෝහය", "මූලාංකුරය", "ග්‍රාහකයේ හා අනුජයේ කැම්බියම් පටක එකිනෙකට හොඳින් ස්පර්ශ විය යුතුය."),
    q("පත්‍රවල පිෂ්ඨය සෑදීමට ආලෝකය අවශ්‍ය බව පෙන්වන පරීක්ෂණයේදී පත්‍රයේ කොටසක් වැසීමට යොදා ගන්නේ කුමක්ද?", "කළු කඩදාසි පටියක්", "විනිවිද පෙනෙන පොලිතීන්", "රතු සෙලෝපේන්", "තෙත් රෙදි කැබැල්ලක්", "කළු කඩදාසියෙන් වැසූ කොටසට ආලෝකය නොලැබෙන නිසා අයඩින් සමඟ දුඹුරු පැහැව පවතී."),
    q("සජීවී ශාකවලින් ජල වාෂ්ප පිටවන බව තහවුරු කිරීමට යොදන නිර්ජලීය කොබෝල්ට් ක්ලෝරයිඩ් කඩදාසියේ වර්ණ විපර්යාසය කුමක්ද?", "නිල් පැහැයේ සිට රෝස පැහැයට හැරීම", "රෝස පැහැයේ සිට නිල් පැහැයට හැරීම", "සුදු පැහැයේ සිට නිල් පැහැයට හැරීම", "කොළ පැහැයේ සිට කහ පැහැයට හැරීම", "තෙතමනය හමුවේ නිර්ජලීය කොබෝල්ට් ක්ලෝරයිඩ් රෝස පැහැ ගැන්වේ."),
    q("ජලය පසේ සිට ශාකයේ පත්‍ර වෙත ළඟා වන නිවැරදි මාර්ග අනුපිළිවෙළ කුමක්ද?", "මූල කේශ → බාහිකය → සෛලම → පත්‍ර මධ්‍යස්තරය", "මූල කේශ → ෆ්ලෝයම → සෛලම → පත්‍ර රන්ධ්‍ර", "අපිචර්මය → කැම්බියම → මජ්ජාව → ෆ්ලෝයම", "සෛලම → මූල කේශ → අපිචර්මය → රන්ධ්‍ර", "ජලය ආස්‍රැතියෙන් මූල කේශ හරහා ඇතුළු වී සෛලමයෙන් ඉහළ නගී."),
    q("ශාක පත්‍රයක ආහාර නිෂ්පාදන ස්ථානයේ සිට සංචිත ස්ථාන දක්වා පරිවහනය සිදුවන ක්‍රියාවලිය හඳුන්වන්නේ කෙසේද?", "පරිසංක්‍රමණය (Translocation)", "උත්ස්වේදනය", "ආස්‍රැතිය", "බිංදුදය", "සුක්‍රෝස් ෆ්ලෝයමය ඔස්සේ දෙදිශාවටම පරිසංක්‍රමණය වේ."),
    q("පත්‍ර රන්ධ්‍ර විවෘත වීම උත්තේජනය කරන ප්‍රධාන පාරිසරික සාධකය කුමක්ද?", "ආලෝකය", "අඳුර", "ඉහළ CO₂ සාන්ද්‍රණය", "ජල හිඟය", "දිවා කාලයේදී ආලෝකය ලැබුණු විට පත්‍ර රන්ධ්‍ර විවෘත වේ."),
    q("දැඩි නියං කාලයකදී ශාක පත්‍ර රන්ධ්‍ර වැසී යාමට සෘජුවම උපකාරී වන හෝමෝනය කුමක්ද?", "ඇබ්සිසික් අම්ලය", "ඔක්සීන්", "සයිටොකයිනින්", "ජිබරලීන්", "ඇබ්සිසික් අම්ලය ආතති හෝමෝනයක් ලෙස ක්‍රියා කර ජල හානිය වළක්වයි."),
    q("සපුෂ්ප ශාකයක සම්පූර්ණ පුෂ්පයක පිටතින්ම පිහිටි කොළ පැහැති වටය හඳුන්වන්නේ කුමන නමින්ද?", "මණිය (Calyx)", "මුකුටය (Corolla)", "පුමංගය", "ජායාංගය", "මණි පත්‍ර පොහොට්ටු අවධියේදී පුෂ්පයේ අභ්‍යන්තර කොටස් ආරක්ෂා කරයි."),
    q("ද්විලිංගික පුෂ්පයක් යනු කුමක්ද?", "එකම පුෂ්පයේ පුමංගය හා ජායාංගය යන දෙකම පිහිටීම", "පුමංගය පමණක් පිහිටීම", "ජායාංගය පමණක් පිහිටීම", "මණිපත්‍ර පමණක් පිහිටීම", "වද, කොබෝලීල හා මෑ පුෂ්ප ද්විලිංගික පුෂ්ප වේ."),
    q("ඒකලිංගික පුෂ්ප හටගන්නා ශාක යුගලයකට උදාහරණයක් වන්නේ කුමක්ද?", "පැපොල් හා වට්ටක්කා", "වද හා කටරොළු", "දෙහි හා අඹ", "මෑ හා බෝංචි", "වට්ටක්කා පුෂ්පවල ජායාංගී හා පුමංගී පුෂ්ප වෙන වෙනම පිහිටයි."),
    q("පරාග කලංකය මත තැන්පත් වීමෙන් අනතුරුව සිදු වන ජීව විද්‍යාත්මක ක්‍රියාවලිය කුමක්ද?", "සංසේචනය", "පරාගණය", "බීජ ව්‍යාප්තිය", "උත්ස්වේදනය", "පරාග නාලය හරහා පැමිණි පුරුෂ ජන්මාණුව ඩිම්බ කෝෂයේ ඩිම්බ සෛලය හා එක් වේ."),
    q("සපුෂ්ප ශාකයක සංසේචනයෙන් පසු හටගන්නා බීජයේ ප්‍රරෝහණයේදී කඳ බවට වර්ධනය වන කොටස කුමක්ද?", "ප්‍රරෝහාංකුරය (Plumule)", "මූලාංකුරය (Radicle)", "බීජ පත්‍රය", "බීජාවරණය", "මූලාංකුරය මූල පද්ධතිය බවටත් ප්‍රරෝහාංකුරය ප්‍රරෝහ පද්ධතිය බවටත් පත්වේ."),
    q("සතුන් මඟින් ව්‍යාප්ත වන ඇට්ටේරියා, කතුරු මුරුංගා නොවන ගොකටු සහ නාගදරණ බීජවල දැකිය හැකි ලක්ෂණය කුමක්ද?", "සතුන්ගේ ලොම්වල හා ඇඳුම්වල ඇලෙන කොකු හෝ කටු පිහිටීම", "පිහාටු වැනි කෙඳි තිබීම", "වායු කුහර තිබීම", "පුපුරා යන කරල් තිබීම", "කොකු සහිත බීජ සතුන් මගින් දුර ඈතට ගෙන යයි."),
    q("පළතුරු කන පක්ෂීන් මඟින් කොහොඹ, පේර සහ නුග බීජ ව්‍යාප්ත වීමට එම බීජ සතු විශේෂ ලක්ෂණය කුමක්ද?", "ජීර්ණ එන්සයිමවලට ඔරොත්තු දෙන ඝන බීජාවරණයක් තිබීම", "විශාල පියාපත් තිබීම", "ජලයේ පාවීමේ හැකියාව", "කටු පිහිටීම", "පක්ෂි මළපහ සමඟ බීජ නිරුපද්‍රිතව පසට පතිත වේ."),
    q("බීජ රහිත මිදි සහ අන්නාසි වැනි පැළවල ස්වාභාවික වර්ධක ප්‍රචාරණය සිදු වන්නේ කුමන ව්‍යුහ මඟින්ද?", "මෝරියන් (Suckers) සහ පඳුරු මඟින්", "බල්බ මඟින්", "පත්‍ර අංකුර මඟින්", "ධාවක මඟින්", "අන්නාසි, කෙසෙල් හා කපුරු ශාක මෝරියන් මඟින් ප්‍රචාරණය වේ."),
    q("වද, රෝස සහ මඤ්ඤොක්කා වැනි ශාක කෘෂිකර්මාන්තයේදී පහසුවෙන් බෝ කරගන්නා ක්‍රමය කුමක්ද?", "අතු කැබලි සිටුවීම", "බල්බ සිටුවීම", "මූල කැබලි සිටුවීම", "බීජ පැළ කිරීම", "දඬු කැබලි මඟින් ඉක්මනින් අංකුර හා මුල් අද්දවා ගත හැක."),
    q("කළු ගම්මිරිස් වැලක් වර්ධක ප්‍රචාරණය කිරීමේදී පොළොවට සවි වීමට උපකාරී වන මූල විශේෂය කුමක්ද?", "ආරෝහක මුල්", "කඳු මුල්", "ශ්වසන මුල්", "කරටි මුල්", "ගම්මිරිස් හා බුලත් වැල්වල ආධාරකයක එල්ලී වැඩීමට ආරෝහක මුල් ඇත."),
    q("කඩොලාන පරිසර පද්ධතියක වැඩෙන කිරල සහ රතමිල්ල ශාකවල පොළොවෙන් ඉහළට වැඩෙන විශේෂ මුල් මොනවාද?", "ශ්වසන මුල් (වායුධර මුල්)", "මූල ගැටිති", "කඳු මුල්", "ආකන්ද මුල්", "කඩොලාන මඩේ ඔක්සිජන් අඩු බැවින් ශ්වසන මුල් හරහා වාතය ලබා ගනී."),
    q("නුග ගසේ අතුවලින් පහළට එල්ලී පොළොවට සවි වී අතු දරා සිටින විශේෂිත මුල් මොනවාද?", "කයිරු මුල් (Prop roots)", "කඳු මුල් (Stilt roots)", "ශ්වසන මුල්", "පරපෝෂී මුල්", "වැටකෙයියා ගසේ ඇලයට වැඩෙන මුල් කඳු මුල් වන අතර නුග ගසේ සිරස්ව ඇත්තේ කයිරු මුල්ය."),
    q("කඳේ පැතිරීම හා ආලෝකය ලබා ගැනීම උපරිම කිරීමට ශාක කඳ මත පත්‍ර සැකසී ඇති ආකාරය හඳුන්වන්නේ කෙසේද?", "පත්‍ර වින්‍යාසය (Phyllotaxy)", "නාරටි වින්‍යාසය", "පුෂ්ප වින්‍යාසය", "මූල වින්‍යාසය", "පත්‍ර එකිනෙකට මුවා නොවන සේ සකස් වී ඇත."),
    q("ශාක පත්‍ර සම්පූර්ණයෙන් හැලී ඇති පැළෑටියක කඳ කොළ පැහැති වී ප්‍රභාසංස්ලේෂණය සිදු කරන ශාකයකට උදාහරණය කුමක්ද?", "පතොක් (Opuntia)", "මහෝගනී", "අඹ", "තේක්ක", "පතොක් ශාකයේ කඳ පත්‍රාභ කඳක් (Phylloclade) ලෙස විකරණය වී ඇත."),
    q("නියඟයට ඔරොත්තු දීම සඳහා පතොක් කඳේ ගබඩා වී ඇති ප්‍රධාන සංඝටකය කුමක්ද?", "ජලය හා ශ්ලේෂ්මල", "තෙල්", "පිෂ්ඨය පමණි", "වාතය", "මාංසල කඳ තුළ ජලය රඳවා ගැනීමේ පටක පිහිටා ඇත."),
    q("මෑ, බෝංචි සහ දඹල ශාකවල ඉහළට නැගීම සඳහා ආධාරකයේ වෙළී යන සිහින් දඟර වැනි ව්‍යුහ මොනවාද?", "ආකර්ෂණ (පහුරු/තන්තු)", "කටු", "ප්‍රකන්ද", "ධාවක", "වැල් වර්ග ආලෝකය සොයා ඉහළට නැගීමට ආකර්ෂණ භාවිත කරයි."),
    q("බූගන්විලියා (කඩදාසි මල්) ශාකයේ දීප්තිමත් වර්ණවත් කොටස් ඇත්ත වශයෙන්ම කුමන ශාක ව්‍යුහද?", "නිපත්‍ර (Bracts)", "මණි පත්‍ර", "පරාගධානි", "ඵලාවරණ", "කුඩා සුදු පැහැති සත්‍ය පුෂ්ප වටා වර්ණවත් නිපත්‍ර පිහිටා කෘමීන් ආකර්ෂණය කරයි."),
    q("වී කරලක් හෝ පොල් මලක් යනු කුමක්ද?", "පුෂ්ප මංජරියකි", "තනි පුෂ්පයකි", "සංයුක්ත පත්‍රයකි", "ඵලයකි", "පොදු අක්ෂයක් මත පුෂ්ප රාශියක් පිහිටීම පුෂ්ප මංජරියකි."),
    q("පොල් ගෙඩියේ ආහාරයට ගන්නා සුදු පැහැති මදය සහ කුරුම්බා වතුර යනු බීජයේ කුමන කොටසද?", "භ්‍රෑණ පෝෂය", "බීජ පත්‍රය", "ඵලාවරණය", "බීජාවරණය", "කුරුම්බා වතුර යනු ද්‍රව භ්‍රෑණ පෝෂයයි."),
    q("අඹ හා පොල් වැනි ඵල වර්ගීකරණයේදී ඇතුළත දැඩි ඇටයක් සහිත මාංසල ඵල හඳුන්වන්නේ කුමන නමින්ද?", "අෂ්ටිල ඵල (Drupes)", "බෙරි ඵල", "කරල්", "කෝෂ", "අෂ්ටිල ඵලවල අන්තඃඵලාවරණය ඉතා දෘඪ වේ."),
    q("තක්කාලි, පේර සහ කෙසෙල් අයත් වන්නේ කුමන ඵල කාණ්ඩයටද?", "මෘදුල ඵල (Berries)", "අෂ්ටිල ඵල", "කරල්", "පුපුරන ඵල", "මෘදුල ඵලවල බීජ රාශියක් මාංසල පල්පය තුළ ගිලී ඇත."),
    q("රනිල කුලයේ ශාකවල දෙපැත්තෙන්ම පැළී බීජ නිදහස් වන වියළි ඵල වර්ගය කුමක්ද?", "රනිල (Legumes / කරල්)", "කෝෂ", "අෂ්ටිල", "මෘදුල", "මෑ, බෝංචි සහ සියඹලා රනිල ඵල වේ."),
    q("ප්‍රභාසංස්ලේෂණයේදී නිපදවෙන ග්ලූකෝස් අණුවකට කාබන් පරමාණු කීයක් අඩංගු වේද?", "6", "3", "12", "5", "ග්ලූකෝස් අණුවක රසායනික සූත්‍රය C₆H₁₂O₆ වේ."),
    q("ප්‍රභාසංස්ලේෂණයේ සමතුලිත රසායනික සමීකරණය අනුව ග්ලූකෝස් අණුවක් සෑදීමට CO₂ අණු කීයක් අවශ්‍ය වේද?", "6", "1", "3", "12", "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂."),
    q("ප්‍රභාසංස්ලේෂණයේදී ශාක පත්‍රයක ආලෝකය වැඩිපුරම අවශෝෂණය වන වර්ණ ආලෝක යුගලය කුමක්ද?", "රතු සහ නිල් ආලෝකය", "කොළ සහ කහ ආලෝකය", "කොළ සහ සුදු ආලෝකය", "දම් සහ අධෝරක්ත", "හරිතප්‍රද කොළ ආලෝකය පරාවර්තනය කරන බැවින් පත්‍ර කොළ පැහැයෙන් දිස්වේ."),
    q("පත්‍රයක් තුළ ප්‍රභාසංස්ලේෂණය සිදුවීමේදී දිවා කාලයේදී ශාකයෙන් පිටවන වායුව කුමක්ද?", "ඔක්සිජන්", "නයිට්‍රජන්", "කාබන් මොනොක්සයිඩ්", "ආගන්", "නිපදවෙන ඔක්සිජන්වලින් කොටසක් ශ්වසනයට ගෙන ඉතිරිය පිට කරයි."),
    q("සෛලම නාලවල ජල අණු එකිනෙකට බැඳී අඛණ්ඩ ජල කඳක් ලෙස ඉහළට ඇදීමට උපකාරී වන ආකර්ෂණ බලය කුමක්ද?", "සංසක්ති හා ආසක්ති බල", "චුම්භක බල", "ගුරුත්වාකර්ෂණ බල", "විකර්ෂණ බල", "ජල අණු අතර සංසක්ති බලත් සෛලම බිත්ති සමඟ ආසක්ති බලත් ක්‍රියා කරයි."),
    q("ශාක පත්‍රවල පිෂ්ඨය පරීක්ෂාවේදී එතනෝල් රත් කිරීමට සෘජු දැල්ලක් භාවිත නොකර ජල තාපකයක් (Water bath) භාවිත කරන්නේ ඇයි?", "එතනෝල් ඉතා ඉක්මනින් ගිනි ඇවිලෙන සුළු ද්‍රවයක් බැවිනි", "එතනෝල් අයිස් බවට පත්වන බැවිනි", "ජලය හරිතප්‍රද දිය කරන බැවිනි", "පිෂ්ඨය විනාශ වන බැවිනි", "රසායනාගාර ආරක්ෂාව සඳහා ජල තාපකයක් භාවිත කිරීම අනිවාර්ය වේ."),
    q("බීජ පැළයක මුල හා කඳ ගුරුත්වයට දක්වන ප්‍රතිචාරය අධ්‍යයනය කිරීමට යොදාගන්නා උපකරණය කුමක්ද?", "ක්ලිනොස්ටැටය (Clinostat)", "පෝටෝමීටරය", "කැලරිමීටරය", "බැරෝමීටරය", "ක්ලිනොස්ටැටය මගින් ගුරුත්වයේ බලපෑම උදාසීන කළ හැක."),
    q("සජීවී ශාක සෛල අතර සෛල බිත්ති මගින් ශාකයට සෘජු බවක් ලැබෙන්නේ සෛලවල කුමන තත්ත්වය නිසාද?", "ශූනතාව (Turgidity)", "මැලවීම", "ප්ලාස්ම විච්ඡේදනය", "විජලනය", "රික්තක ජලයෙන් පිරී ඇති විට පැළෑටි ඍජුව පවතී."),
    q("ශාක මුල් පස තුළ ජලය ඇති දිශාවට වර්ධනය වීම හඳුන්වන්නේ කුමන වර්තන චලනය ලෙසද?", "ධන ජලවර්තනය", "ධන ප්‍රකාශවර්තනය", "ඍණ ගුරුත්වවර්තනය", "සන්නමන චලනය", "ජලවර්තනය ගුරුත්වවර්තනයට වඩා ප්‍රබල විය හැක."),
    q("වල් පැළෑටි පාලනය නොකළහොත් බෝග ශාකවල අස්වැන්න අඩු වීමට ප්‍රධාන හේතුව කුමක්ද?", "ආලෝකය, ජලය හා ඛනිජ සඳහා තරග කිරීම", "මල් පරාගණය නැවැත්වීම", "පසේ ඔක්සිජන් වැඩි කිරීම", "මූල පීඩනය වැඩි කිරීම", "අන්තර්-විශේෂ තරගය නිසා බෝග වර්ධනය දුර්වල වේ."),
    q("ශාකයක ස්පර්ශාවර්තන (Thigmotropism) චලනයට හොඳම උදාහරණය කුමක්ද?", "වැල්වල ආකර්ෂණ ආධාරකයක වෙළීම", "සූරියකාන්ත මල හිරු දෙසට හැරීම", "මුල් පොළොව යටට යාම", "නිදිකුම්බා පත්‍ර වැසීම", "ආධාරකය ස්පර්ශ වන පැත්තේ වර්ධනය අඩු වී වෙළී යයි."),
    q("දේහයේ කොටසක් කැපූ පසු නව මුල් අද්දවා ගැනීමට උද්‍යාන විද්‍යාවේදී කෘත්‍රිමව යොදන රසායනිකය කුමක්ද?", "මුල් ඇද්දවීමේ හෝමෝන (IBA/NAA ඔක්සීන)", "ඇබ්සිසික් අම්ලය", "එතිලීන්", "අයඩින්", "ඔක්සීන කුඩු කැපුම් පෘෂ්ඨයේ ආලේප කිරීමෙන් මූල වර්ධනය වේගවත් වේ."),
    q("පත්‍ර මඟින් ආහාර නිපදවීමට පොහොර ලෙස භාවිත කරන NPK යනු කුමන මූලද්‍රව්‍ය තුනද?", "නයිට්‍රජන්, පොස්පරස්, පොටෑසියම්", "නියොන්, ප්ලැටිනම්, ක්‍රිප්ටන්", "සෝඩියම්, පොටෑසියම්, කැල්සියම්", "නයිට්‍රජන්, පොලෝනියම්, කාබන්", "NPK යනු ශාකවලට වැඩිපුර අවශ්‍ය ප්‍රාථමික මහා පෝෂක තුනය."),
    q("ශාකවල පසෙන් උරාගන්නා නයිට්‍රජන් ප්‍රධාන වශයෙන් වැදගත් වන්නේ කුමන ජෛව අණු සංස්ලේෂණයටද?", "ප්‍රෝටීන සහ න්‍යෂ්ටික අම්ල", "සෙලියුලෝස් සහ පිෂ්ඨය", "ලිපිඩ සහ මේද අම්ල", "සුක්‍රෝස් සහ ග්ලූකෝස්", "නයිට්‍රජන් ඌන වූ විට ශාක වර්ධනය කුරු වී පත්‍ර කහ පැහැ වේ."),
    q("සිඟිති පැළෑටියක කඳ පැහැදිලිව හරිතප්‍රද සාදා කොළ පැහැ ගැන්වීමට අත්‍යවශ්‍ය වන ඛනිජ යුගලය කුමක්ද?", "මැග්නීසියම් සහ නයිට්‍රජන්", "කැල්සියම් සහ සෝඩියම්", "බෝරෝන් සහ ක්ලෝරීන්", "පොස්පරස් සහ සල්ෆර්", "ක්ලෝරොෆිල් අණුවේ ව්‍යුහය තුළ නයිට්‍රජන් හා මැග්නීසියම් අඩංගු වේ."),
    q("බීජ පැළවීමේදී පළමුවෙන් බීජාවරණය පළාගෙන පිටතට පැමිණෙන ව්‍යුහය කුමක්ද?", "මූලාංකුරය (Radicle)", "ප්‍රරෝහාංකුරය", "බීජ පත්‍ර", "පළමු පුෂ්පය", "පැළෑටිය පසට සවි වී ජලය උරා ගැනීමට මූලාංකුරය මුලින්ම වර්ධනය වේ.")
  )
}
